package vn.restaurant.ui;
import vn.restaurant.model.*;import vn.restaurant.service.*;import vn.restaurant.util.*;import javax.swing.*;import java.awt.*;import java.awt.print.*;
public class FrmXacNhanThanhToan extends JDialog {
 private boolean paid=false;public boolean isPaid(){return paid;}
 public FrmXacNhanThanhToan(JDialog owner,CtlThanhToanHoaDon ctl,ClsHoaDon hd){super(owner,"Xác nhận thanh toán",true);setSize(650,430);setResizable(false);setLocationRelativeTo(owner);JPanel root=Theme.panel(new BorderLayout(0,20));root.setBorder(BorderFactory.createEmptyBorder(22,28,22,28));setContentPane(root);root.add(Theme.title("Xác nhận thanh toán"),BorderLayout.NORTH);
 JPanel center=Theme.panel(new BorderLayout(0,16));JLabel question=new JLabel("<html><b>Bạn có chắc chắn muốn xác nhận thanh toán hóa đơn này không?</b></html>");question.setFont(Theme.FONT);center.add(question,BorderLayout.NORTH);JPanel fields=Theme.panel(new GridLayout(4,2,12,12));fields.setBackground(Theme.LIGHT);fields.setBorder(BorderFactory.createEmptyBorder(18,20,18,20));for(String s:new String[]{"Mã hóa đơn:",hd.ma,"Bàn:","Bàn "+hd.maBan,"Tổng tiền thanh toán:",Theme.money(hd.tongTien()),"Trạng thái hiện tại:","Chưa thanh toán"}){JLabel l=new JLabel(s);l.setFont(Theme.FONT.deriveFont(s.equals(Theme.money(hd.tongTien()))?Font.BOLD:Font.PLAIN));fields.add(l);}center.add(fields,BorderLayout.CENTER);root.add(center,BorderLayout.CENTER);
 JPanel actions=Theme.panel(new FlowLayout(FlowLayout.RIGHT,12,6));JButton back=Theme.button("Không / Quay lại",false),ok=Theme.button("Xác nhận và in hóa đơn",true);actions.add(back);actions.add(ok);root.add(actions,BorderLayout.SOUTH);back.addActionListener(e->dispose());ok.addActionListener(e->{try{ctl.xacNhan(hd.maBan);paid=true;try{printInvoice(hd);JOptionPane.showMessageDialog(this,"Thanh toán thành công và đã gửi lệnh in hóa đơn.");}catch(PrinterException pe){JOptionPane.showMessageDialog(this,"Thanh toán thành công, nhưng không thể in hóa đơn: "+pe.getMessage()+"\nCó thể in lại từ chức năng in khi được bổ sung.","Lỗi máy in",JOptionPane.WARNING_MESSAGE);}dispose();}catch(IllegalStateException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Lỗi",JOptionPane.ERROR_MESSAGE);}});
 }
 private void printInvoice(ClsHoaDon hd)throws PrinterException{PrinterJob job=PrinterJob.getPrinterJob();job.setJobName("Hoa don "+hd.ma);job.setPrintable((graphics,pageFormat,pageIndex)->{if(pageIndex>0)return Printable.NO_SUCH_PAGE;Graphics2D g=(Graphics2D)graphics;g.translate(pageFormat.getImageableX(),pageFormat.getImageableY());g.setColor(Color.BLACK);g.setFont(new Font("SansSerif",Font.PLAIN,12));int y=25;g.drawString("HOA DON THANH TOAN - "+hd.ma,15,y);y+=25;g.drawString("Ban: "+hd.maBan+" | Ngay: "+hd.ngayLap,15,y);y+=25;for(ClsChiTietHoaDon c:hd.chiTiet){g.drawString(c.tenMon()+" x"+c.soLuong()+" - "+Theme.money(c.thanhTien()),15,y);y+=22;}g.drawString("TONG TIEN: "+Theme.money(hd.tongTien()),15,y+15);return Printable.PAGE_EXISTS;});if(job.printDialog())job.print();else throw new PrinterException("Người dùng đã hủy hộp thoại in.");}
}
